begin;
select no_plan();
insert into auth.users(id,email) values ('00000000-0000-0000-0000-000000006101','advisory-a@example.test'),('00000000-0000-0000-0000-000000006102','advisory-b@example.test'),('00000000-0000-0000-0000-000000006103','advisory-outside@example.test');
insert into public.profiles(id,name,age,sex,height_cm,weight_kg,units,experience,equipment,days_per_week,session_minutes,goal,dietary_pattern,allergies,cooking_time_minutes,meal_budget)
select id,'Same name',30,'female',165,65,'metric','beginner',array['none'],3,30,'maintain',case when email='advisory-a@example.test' then 'Vegan low-carb' else 'No restrictions' end,case when email='advisory-a@example.test' then array['soy'] else array['cucumber'] end,0,4 from auth.users where email like 'advisory-%@example.test';
insert into public.goals(app_id,user_id,goal_type,effective_date,weekly_workout_target) select 'advisory-goal-'||id,id,'maintain','2026-09-01',3 from public.profiles where id::text like '%00610_';
insert into public.daily_targets(app_id,user_id,goal_row_id,version,effective_date,calories,protein_g,carbs_g,fat_g,bmr,bmi,tdee,activity_factor,formula,disclaimer)
select 'advisory-target-'||user_id,user_id,row_id,1,'2026-09-01',2400,120,100,65,1400,23.9,2400,1.5,'test','Estimates only' from public.goals where app_id like 'advisory-goal-%';
select is(private.recipe_cost_score((select m from public.meals m where app_id='meal-korean-beef-bowl')),0::numeric,'seeded recipe cost is zero');
select lives_ok($$select private.assert_generation_recipe((select m from public.meals m where app_id='meal-korean-beef-bowl'),(select p from public.profiles p where id='00000000-0000-0000-0000-000000006101'))$$,'diet allergy source and cost conflicts do not reject usable recipes');
select ok(private.recipe_preference_warnings((select m from public.meals m where app_id='meal-korean-beef-bowl'),(select p from public.profiles p where id='00000000-0000-0000-0000-000000006101')) @> '[{"code":"avoided-food"}]','avoided ingredients are warned');
select ok(private.recipe_preference_warnings((select m from public.meals m where app_id='meal-korean-beef-bowl'),(select p from public.profiles p where id='00000000-0000-0000-0000-000000006101')) @> '[{"code":"diet"}]','vegan conflict is warned');
select ok(private.recipe_preference_warnings((select m from public.meals m where app_id='meal-korean-beef-bowl'),(select p from public.profiles p where id='00000000-0000-0000-0000-000000006101')) @> '[{"code":"source-nutrition"}]','source nutrition is warned');
select ok(not has_function_privilege('authenticated','private.planning_preference_review(uuid,jsonb,jsonb)','execute'),'private reviewer inaccessible');
insert into public.foods(app_id,owner_user_id,is_system,name,serving_label,serving_grams,serving_unit,calories,protein_g,carbs_g,fat_g,category,source,source_version,estimated,confidence,value_source,estimate_range)
values('advisory-ai-food','00000000-0000-0000-0000-000000006101',false,'Estimated chicken','one serving',100,'g',200,10,20,8,'Other','AI estimate','model-v1',true,'low','ai_estimate','{"calories":{"low":180,"base":200,"high":220},"proteinG":{"low":8,"base":10,"high":12},"carbsG":{"low":18,"base":20,"high":22},"fatG":{"low":6,"base":8,"high":10}}');
insert into public.meals(app_id,owner_user_id,is_system,name,servings,notes,complexity,meal_slots) values('advisory-ai-recipe','00000000-0000-0000-0000-000000006101',false,'Estimated recipe',2,'Cook.','easy',array['lunch']);
insert into public.meal_ingredients(meal_row_id,food_row_id,ingredient_order,servings) select m.row_id,f.row_id,1,2 from public.meals m cross join public.foods f where m.app_id='advisory-ai-recipe' and f.app_id='advisory-ai-food';
select lives_ok($$select private.assert_generation_recipe((select m from public.meals m where app_id='advisory-ai-recipe'),(select p from public.profiles p where id='00000000-0000-0000-0000-000000006101'))$$,'usable AI recipe nutrition is structurally allowed');
select is(private.normalize_planned_meal_record('{"mealId":"advisory-ai-recipe","servings":1}','00000000-0000-0000-0000-000000006101')->>'source','AI-estimated recipe','AI recipe is never labeled trusted catalog');
select is(private.normalize_planned_meal_record('{"mealId":"advisory-ai-recipe","servings":1}','00000000-0000-0000-0000-000000006101')->>'confidence','low','AI uncertainty retained on planned record');
select is((private.normalize_planned_meal_record('{"mealId":"advisory-ai-recipe","servings":1}','00000000-0000-0000-0000-000000006101')->>'expectedCarbsG')::numeric,20::numeric,'provenance correction does not change numeric recipe carbs');

select ok(not has_function_privilege('anon','private.recipe_preference_warnings(public.meals,public.profiles)','execute'),'anonymous cannot inspect private recipe matches');
create temp table advisory_state(name text primary key,value jsonb);
grant all on advisory_state to authenticated,service_role;
set local role authenticated;
set local "request.jwt.claim.role"='authenticated';
set local "request.jwt.claim.sub"='00000000-0000-0000-0000-000000006101';
insert into advisory_state values('invite',public.cooking_group_command('{"action":"invite","idempotencyKey":"advisory-invite"}'));
set local "request.jwt.claim.sub"='00000000-0000-0000-0000-000000006102';
select public.cooking_group_command(jsonb_build_object('action','inspect-pin','pin',(select value->>'pin' from advisory_state where name='invite')));
select public.cooking_group_command(jsonb_build_object('action','join','pin',(select value->>'pin' from advisory_state where name='invite'),'groupRevision',1,'idempotencyKey','advisory-join'));
set local role service_role;
set local "request.jwt.claim.role"='service_role';
insert into advisory_state values('input',jsonb_build_object('reviewPolicyVersion','advisory_v1','groupId',(select value->'group'->>'id' from advisory_state where name='invite'),'weekOf','2026-10-18','memberIds',jsonb_build_array('00000000-0000-0000-0000-000000006101','00000000-0000-0000-0000-000000006102'),'selectedDates',jsonb_build_array('2026-10-18'),'mode','fill','recipes',jsonb_build_array(jsonb_build_object('id','meal-korean-beef-bowl','revision',(select revision from public.meals where app_id='meal-korean-beef-bowl'),'maxBatches',2)),'seed','test','overrides','{}'::jsonb));
insert into advisory_state values('context',public.get_group_planning_context('00000000-0000-0000-0000-000000006101',(select value from advisory_state where name='input')));
select is((select value->>'preferencePolicy' from advisory_state where name='context'),'advisory_v1','server selects advisory allocator');
insert into advisory_state values('preview',public.store_group_planning_preview('00000000-0000-0000-0000-000000006101',(select value from advisory_state where name='input'),jsonb_build_object('basis',(select value->>'basis' from advisory_state where name='context'),'warnings','[]'::jsonb,'batches','[]'::jsonb,'replacements','[]'::jsonb,'assignments',jsonb_build_array(jsonb_build_object('id','advisory-a','memberId','00000000-0000-0000-0000-000000006101','recipeId','meal-korean-beef-bowl','date','2026-10-18','slot','lunch','servings',3),jsonb_build_object('id','advisory-b','memberId','00000000-0000-0000-0000-000000006102','recipeId','meal-korean-beef-bowl','date','2026-10-18','slot','lunch','servings',1)))));
select ok(not (select value ? 'memberReviews' from advisory_state where name='preview'),'preview never exposes private member review map');
select ok((select value->'preferenceReview'->'recipeWarnings' from advisory_state where name='preview')::text like '%soy%','actor sees own warning');
select ok((select value->'preferenceReview'->'recipeWarnings' from advisory_state where name='preview')::text not like '%cucumber%','actor cannot see another members avoided-food term');
select is(jsonb_array_length((select value->'preferenceReview'->'dailyWarnings' from advisory_state where name='preview')),1,'over-cap day is advisory');
set local role authenticated;
set local "request.jwt.claim.role"='authenticated';
set local "request.jwt.claim.sub"='00000000-0000-0000-0000-000000006101';
select throws_ok($$select public.commit_cooking_group_plan(jsonb_build_object('previewId',(select value->>'id' from advisory_state where name='preview'),'acknowledged',false,'idempotencyKey','advisory-no-ack'))$$,'P0001',null,'acknowledgment required');
select lives_ok($$select public.commit_cooking_group_plan(jsonb_build_object('previewId',(select value->>'id' from advisory_state where name='preview'),'acknowledged',true,'idempotencyKey','advisory-commit'))$$,'reviewed diet allergy time and carb conflicts can be saved');
select is((select preference_policy from public.meal_plans where week_of='2026-10-18' order by version desc limit 1),'advisory_v1','new generation stores advisory policy');
select is(jsonb_array_length(public.get_nutrition_week('2026-10-18')->'plannedMeals'),1,'own assignment is visible in daily read');
select ok((select summary from public.cooking_generations)::text not like '%soy%','shared generation contains no private allergy terms');
select ok(not (select summary ? 'memberReviews' from public.cooking_generations),'shared generation has no member review map');
select is((public.get_cooking_group_week('2026-10-18')->'generation'->'assignmentCounts'->0->>'count')::integer,1,'summary counts saved assignments');
select ok((public.get_cooking_group_week('2026-10-18')->'generation'->'personalReview')::text like '%soy%','owner can reopen own review');
select is((select count(*) from public.cooking_generation_notices),1::bigint,'notice RLS isolates member rows');
select ok((select preference_review from public.cooking_generation_notices)::text not like '%cucumber%','cannot read another member notice details');
insert into advisory_state values('own-review',public.get_cooking_group_week('2026-10-18')->'generation'->'personalReview');
select lives_ok($$select public.mutate_cooking_group_week(jsonb_build_object('action','edit-assignment','groupId',(select value->>'groupId' from advisory_state where name='input'),'weekOf','2026-10-18','revision',(public.get_cooking_group_week('2026-10-18')->>'revision')::integer,'assignmentId',(select app_id from public.planned_meals order by row_id desc limit 1),'recipeId','meal-korean-beef-bowl','servings',3.25,'skipped',false,'idempotencyKey','advisory-edit'))$$,'accepted advisory assignment remains editable above carb preference');
select is(public.get_cooking_group_week('2026-10-18')->'generation'->'personalReview',(select value from advisory_state where name='own-review'),'later edit preserves generation-time private review');
set local "request.jwt.claim.sub"='00000000-0000-0000-0000-000000006102';
select ok((public.get_cooking_group_week('2026-10-18')->'generation'->'personalReview')::text like '%cucumber%','recipient receives own private warning review');
select ok((public.get_cooking_group_week('2026-10-18')->'generation'->'personalReview')::text not like '%soy%','recipient cannot read creator warnings');
set local "request.jwt.claim.sub"='00000000-0000-0000-0000-000000006103';
select is((select count(*) from public.cooking_generation_notices),0::bigint,'outsider sees no private notices');
select is(public.get_cooking_group_week('2026-10-18')->'group','null'::jsonb,'outsider sees no group generation');
reset role;
set local "request.jwt.claim.sub"='00000000-0000-0000-0000-000000006101';
update public.cooking_generations set summary=jsonb_set(summary,'{assignments}',(select jsonb_agg(a) from jsonb_array_elements(summary->'assignments') a where a->>'memberId'='00000000-0000-0000-0000-000000006101'));
select is((select (c->>'count')::integer from public.cooking_generations g cross join lateral jsonb_array_elements(private.cooking_generation_json(g,'00000000-0000-0000-0000-000000006101')->'assignmentCounts') c where c->>'memberId'='00000000-0000-0000-0000-000000006102'),0,'selected account with no new assignments is explicitly counted as zero');
insert into public.meal_plans(app_id,user_id,week_of,target_row_id,version,supersedes_plan_row_id,preference_policy)
select app_id,user_id,week_of,target_row_id,version+1,row_id,'enforced' from public.meal_plans where user_id='00000000-0000-0000-0000-000000006101' order by version desc limit 1;
select is((select preference_policy from public.meal_plans where user_id='00000000-0000-0000-0000-000000006101' order by version desc limit 1),'advisory_v1','server copy inherits parent policy rather than submitted policy');
select * from finish();
rollback;
